  internal static DataTemplate Template(string body){return (DataTemplate)XamlReader.Parse("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'>"+body+"</DataTemplate>");}
  internal static Window Dialog(Window owner,string title,double width,double height,UIElement content){var d=new Window{Owner=owner,Title=title,Width=width,Height=height,MinWidth=Math.Min(width,480),MinHeight=Math.Min(height,320),WindowStartupLocation=WindowStartupLocation.CenterOwner,ShowInTaskbar=false,FontFamily=owner.FontFamily,FontSize=owner.FontSize,Resources=owner.Resources,Content=new Border{Padding=new Thickness(24,8,24,24),Child=content}};Chrome.Dialog(d,true);return d;}
  internal static Button Button(string text,Action action,bool primary){var b=new Button{Content=text};if(primary)b.SetResourceReference(FrameworkElement.StyleProperty,"Primary");b.Click+=delegate{action();};return b;}
  internal static TextBlock Label(string value,bool muted){var t=new TextBlock{Text=value,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)};t.SetResourceReference(TextBlock.ForegroundProperty,muted?"Muted":"Text");return t;}
  internal static string EditText(Window owner,string heading,string value,string note){var g=Parse("<Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><TextBlock x:Name='Title' FontSize='22' FontWeight='SemiBold'/><TextBlock x:Name='Note' Grid.Row='1' Margin='0,12,0,16' TextWrapping='Wrap' Foreground='{DynamicResource Muted}'/><TextBox x:Name='Value' Grid.Row='2' VerticalAlignment='Top'/><StackPanel Grid.Row='3' Orientation='Horizontal' HorizontalAlignment='Right' Margin='0,18,0,0'><Button x:Name='Cancel' Content='取消' IsCancel='True'/><Button x:Name='Save' Content='确认' Style='{DynamicResource Primary}'/></StackPanel>");((TextBlock)g.FindName("Title")).Text=heading;((TextBlock)g.FindName("Note")).Text=note;var input=(TextBox)g.FindName("Value");input.Text=value??"";var d=Dialog(owner,heading,590,340,g);((Button)g.FindName("Save")).Click+=delegate{d.DialogResult=true;};d.Loaded+=delegate{input.Focus();input.SelectAll();};return d.ShowDialog()==true?input.Text:null;}
  internal const string ProgramCell="<Grid ToolTip='{Binding Path}' Margin='4,8'><Grid.ColumnDefinitions><ColumnDefinition Width='38'/><ColumnDefinition Width='*'/></Grid.ColumnDefinitions><Image Source='{Binding Icon}' Width='26' Height='26'/><StackPanel Grid.Column='1' VerticalAlignment='Center'><TextBlock Text='{Binding Name}' FontWeight='SemiBold' TextTrimming='CharacterEllipsis'/><TextBlock Text='{Binding Path}' Foreground='{DynamicResource Muted}' FontSize='11' Margin='0,5,0,0' TextTrimming='CharacterEllipsis'/></StackPanel></Grid>";
 }
 public sealed partial class Controller {
  Grid associationPanel;DataGrid associationGrid;TextBox associationSearch;ComboBox associationMode;Button navAssociation;long pendingRestoreProfile;
  void RenameProgram(Window owner,AppRow row){if(row==null)return;string value=FeatureUi.EditText(owner,"自定义进程名称",row.Name,"只修改列表中的显示名称，不修改文件；留空可恢复原名称");if(value==null)return;try{db.RememberOriginalName(row);db.SetAlias(row.Path,value);foreach(var r in current.Concat(history))db.ApplyName(r);db.ApplyName(row);ApplyFilter();HistoryPresentation.ApplyOrder(Get<DataGrid>("RestoreGrid"));RefreshAssociations();Status("程序显示名称已更新");}catch(Exception ex){ModernDialog.Confirm(owner,ex.Message,"",false);}}
  void EditRestoreArgs(AppRow row){if(row==null)return;if(!Setting("argsEditNoticeSeen",false)){ModernDialog.Confirm(w,"修改后的启动参数会在恢复程序时自动保存，并在下次恢复时继续使用","",false);db.Set("argsEditNoticeSeen","1");}string value=FeatureUi.EditText(w,"编辑启动参数",row.Args,"仅修改此程序的启动参数；恢复时会自动保存");if(value==null)return;if(value.Length>30000||value.IndexOf('\0')>=0){Error(new ArgumentException("启动参数无效或过长"));return;}row.Args=value;row.ArgsKnown=true;db.SaveHistoryChoice(row);}
  void ManageNames(){var rows=db.Aliases();foreach(var row in rows)ProgramPresentation.LoadIcon(row);var d=new ProgramSelectionDialog(w,rows,true,true,true);d.Title="管理自定义程序名称";var b=d.FindName("Confirm") as Button;if(b!=null)b.Content="恢复原名称";if(d.ShowDialog()==true){foreach(var r in d.Chosen)db.SetAlias(r.Path,"");foreach(var r in current.Concat(history))db.ApplyName(r);ApplyFilter();RefreshAssociations();Status("已恢复所选程序的原名称");}}
  void SetupAssociations(){var nav=(StackPanel)Get<Button>("NavRestore").Parent;navAssociation=FeatureUi.Button("⇄   关联启动",()=>Navigate(4),false);navAssociation.SetResourceReference(FrameworkElement.StyleProperty,"Nav");nav.Children.Insert(nav.Children.IndexOf(Get<Button>("NavRestore"))+1,navAssociation);
   associationPanel=FeatureUi.Parse("<Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><Grid Margin='0,0,0,14'><Grid.ColumnDefinitions><ColumnDefinition Width='*'/><ColumnDefinition Width='Auto'/><ColumnDefinition Width='Auto'/><ColumnDefinition Width='Auto'/></Grid.ColumnDefinitions><TextBox x:Name='Search' Style='{DynamicResource SearchInput}' ToolTip='搜索关联程序名称或路径' Margin='0,0,16,0'/><ComboBox x:Name='Mode' Grid.Column='1' MinWidth='170' Margin='0,0,8,0'><ComboBoxItem Content='托盘 / 任务栏程序'/><ComboBoxItem Content='全部运行进程'/></ComboBox><Button x:Name='Refresh' Content='刷新' Grid.Column='2'/><Button x:Name='Pick' Content='◎ 定位窗口' Grid.Column='3'/></Grid><DockPanel Grid.Row='1' Margin='0,0,0,14'><TextBlock x:Name='Count' VerticalAlignment='Center' Foreground='{DynamicResource Muted}'/><StackPanel Orientation='Horizontal' HorizontalAlignment='Right'><Button x:Name='Reset' Content='恢复默认'/></StackPanel></DockPanel><Border Grid.Row='2' Background='{DynamicResource Surface}' CornerRadius='9' BorderBrush='{DynamicResource Line}' BorderThickness='1'><DataGrid x:Name='Rules' AutoGenerateColumns='False' IsReadOnly='False' CanUserAddRows='False' SelectionMode='Single'/></Border><Button x:Name='Select' Grid.Row='3' Content='添加关联程序' Style='{DynamicResource Primary}' HorizontalAlignment='Right' Margin='0,16,0,0'/>");associationPanel.Visibility=Visibility.Collapsed;Grid.SetRow(associationPanel,1);((Grid)Get<Grid>("CurrentPanel").Parent).Children.Add(associationPanel);
   associationGrid=(DataGrid)associationPanel.FindName("Rules");associationSearch=(TextBox)associationPanel.FindName("Search");associationMode=(ComboBox)associationPanel.FindName("Mode");associationMode.SelectedIndex=Get<ComboBox>("ScanMode").SelectedIndex;associationMode.SelectionChanged+=delegate{Get<ComboBox>("ScanMode").SelectedIndex=associationMode.SelectedIndex;};
   associationGrid.Columns.Add(new DataGridTemplateColumn{Header="程序 / 进程",Width=new DataGridLength(1,DataGridLengthUnitType.Star),IsReadOnly=true,CellTemplate=FeatureUi.Template("<ContentControl Content='{Binding Source}' ContentTemplate='{DynamicResource LinkedProgramCell}'/>")});
   associationGrid.Resources["LinkedProgramCell"]=FeatureUi.Template(FeatureUi.ProgramCell);
   associationGrid.Columns.Add(new DataGridTextColumn{Header="来源",Binding=new Binding("Source.Source"),Width=110,IsReadOnly=true});associationGrid.Columns.Add(new DataGridTextColumn{Header="类别",Binding=new Binding("Source.RiskText"),Width=110,IsReadOnly=true});
   associationGrid.Columns.Add(new DataGridTemplateColumn{Header="关联启动的程序",Width=new DataGridLength(1,DataGridLengthUnitType.Star),IsReadOnly=true,CellTemplate=FeatureUi.Template("<ContentControl Content='{Binding Target}' ContentTemplate='{DynamicResource LinkedProgramCell}'/>")});
   associationGrid.Columns.Add(new DataGridTemplateColumn{Header="规则状态",Width=140,CellTemplate=FeatureUi.Template("<CheckBox Style='{DynamicResource Switch}' HorizontalAlignment='Center' IsChecked='{Binding Enabled,Mode=TwoWay,UpdateSourceTrigger=PropertyChanged}'/>")});
   associationGrid.AddHandler(CheckBox.CheckedEvent,new RoutedEventHandler(ToggleAssociation));associationGrid.AddHandler(CheckBox.UncheckedEvent,new RoutedEventHandler(ToggleAssociation));associationSearch.TextChanged+=delegate{FilterAssociations();};
   ((Button)associationPanel.FindName("Refresh")).Click+=delegate{RefreshAssociations();};((Button)associationPanel.FindName("Select")).Click+=delegate{SelectAssociatedProgram(null);};((Button)associationPanel.FindName("Pick")).Click+=delegate{SelectAssociatedProgram(true);};((Button)associationPanel.FindName("Reset")).Click+=delegate{associationSearch.Clear();RefreshAssociations();};
   associationGrid.LoadingRow+=delegate(object s,DataGridRowEventArgs e){var r=(AssociationRule)e.Row.Item;var menu=ProgramPresentation.PathMenu(r.Source,Status,null,RenameMain,null);menu.Resources=w.Resources;var edit=new MenuItem{Header="编辑关联"};edit.Click+=delegate{EditAssociation(w,r.Source,r.Target);RefreshAssociations();};var del=new MenuItem{Header="删除关联"};del.Click+=delegate{if(Ask("确定删除此关联启动规则？","")){db.DeleteAssociation(r.Source.Path);RefreshAssociations();}};menu.Items.Add(edit);menu.Items.Add(del);e.Row.ContextMenu=menu;};ScrollActivity.Attach(associationGrid);RefreshAssociations();
  }
  void RenameMain(AppRow row){RenameProgram(w,row);}
  bool loadingRules;
  void ToggleAssociation(object sender,RoutedEventArgs e){var check=e.OriginalSource as CheckBox;var rule=check==null?null:check.DataContext as AssociationRule;if(rule==null||loadingRules)return;Guard(delegate{db.SetAssociationEnabled(rule.Source.Path,check.IsChecked==true);rule.Enabled=check.IsChecked==true;UpdateLinkedSwitch();ReloadCollections();});}
  void RefreshAssociations(){if(associationGrid==null)return;loadingRules=true;try{var rules=db.Associations();rules.Sort((a,b)=>HistoryPresentation.CompareProgramNames(a.Source,b.Source));foreach(var r in rules){var observed=current.FirstOrDefault(x=>String.Equals(x.Path,r.Source.Path,StringComparison.OrdinalIgnoreCase));r.Source.Source=observed==null?"自定义":observed.Source;r.Source.Risk=observed!=null?observed.Risk:Policy.HighRisk(r.Source.ProcessName,false,false);r.Source.Antivirus=Policy.IsAntivirus(r.Source.ProcessName,r.Source.Path);ProgramPresentation.LoadIcon(r.Source);ProgramPresentation.LoadIcon(r.Target);}associationGrid.ItemsSource=rules;FilterAssociations();UpdateLinkedSwitch();}finally{loadingRules=false;}}
  void FilterAssociations(){if(associationGrid.ItemsSource==null)return;string q=associationSearch.Text.Trim();CollectionViewSource.GetDefaultView(associationGrid.ItemsSource).Filter=o=>{var r=(AssociationRule)o;return (r.Source.Name+" "+r.Source.Path+" "+r.Target.Name+" "+r.Target.Path).IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0;};((TextBlock)associationPanel.FindName("Count")).Text=associationGrid.Items.Count+" 条关联规则 · 关闭后恢复关联程序";}
  async Task<List<AppRow>> AssociationCandidates(){bool all=Get<ComboBox>("ScanMode").SelectedIndex==1,candidates=Setting("candidates",false);string[] custom=db.Query("SELECT key FROM settings WHERE key LIKE 'custom:%'").Select(x=>x[0].Substring(7)).ToArray();return await Task.Run(()=>{var rows=scanPrograms(all,candidates,custom).Rows;foreach(var r in db.Query("SELECT path,name,args,admin,chosen FROM managed").Where(x=>custom.Contains(x[0],StringComparer.OrdinalIgnoreCase)).Select(x=>new AppRow{Path=x[0],Name=x[1],ProcessName=Path.GetFileName(x[0]),Args=x[2],Admin=x[3]=="1",Source="自定义",ArgsKnown=true}))if(!rows.Any(x=>String.Equals(x.Path,r.Path,StringComparison.OrdinalIgnoreCase)))rows.Add(ProgramPresentation.Copy(r));rows=db.FilterVisible(rows);foreach(var r in rows){db.ApplyName(r);ProgramPresentation.LoadIcon(r);}return rows;});}
  void SelectAssociatedProgram(bool? pick){var g=FeatureUi.Parse("<Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='*'/></Grid.RowDefinitions><TextBlock Text='选择关联程序' FontSize='22' FontWeight='SemiBold' Margin='0,0,0,18'/><Grid Grid.Row='1' Margin='0,0,0,16'><Grid.ColumnDefinitions><ColumnDefinition Width='*'/><ColumnDefinition Width='2*'/><ColumnDefinition Width='Auto'/><ColumnDefinition Width='Auto'/></Grid.ColumnDefinitions><TextBox x:Name='Search' Style='{DynamicResource SearchInput}' ToolTip='搜索名称或路径'/><Button x:Name='Refresh' Grid.Column='2' Content='刷新'/><Button x:Name='Pick' Grid.Column='3' Content='◎ 定位窗口'/></Grid><DataGrid x:Name='Programs' Grid.Row='2' AutoGenerateColumns='False' IsReadOnly='True' CanUserAddRows='False' SelectionMode='Single'/>");var d=FeatureUi.Dialog(w,"选择关联程序",Math.Min(1100,SystemParameters.WorkArea.Width*.85),Math.Min(740,SystemParameters.WorkArea.Height*.85),g);var table=(DataGrid)g.FindName("Programs");table.Columns.Add(new DataGridTemplateColumn{Header="程序 / 进程",SortMemberPath="Name",Width=new DataGridLength(1,DataGridLengthUnitType.Star),CellTemplate=FeatureUi.Template(FeatureUi.ProgramCell)});table.Columns.Add(new DataGridTextColumn{Header="来源",Binding=new Binding("Source"),SortMemberPath="Source",Width=150});table.Columns.Add(new DataGridTextColumn{Header="类别",Binding=new Binding("RiskText"),SortMemberPath="RiskText",Width=145});HistoryPresentation.Configure(table);ScrollActivity.Attach(table);var search=(TextBox)g.FindName("Search");Action filter=delegate{if(table.ItemsSource!=null){string q=search.Text.Trim();CollectionViewSource.GetDefaultView(table.ItemsSource).Filter=o=>{var r=(AppRow)o;return (r.Name+" "+r.Path+" "+r.ProcessName).IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0;};HistoryPresentation.ApplyOrder(table);}};
   bool fetching=false,done=false;Func<Task> refresh=async delegate{if(fetching)return;fetching=true;try{var rows=await AssociationCandidates();if(!done){table.ItemsSource=rows;filter();}}catch(Exception ex){if(!done)ModernDialog.Confirm(d,ex.Message,"",false);}finally{fetching=false;}};search.TextChanged+=delegate{filter();};((Button)g.FindName("Refresh")).Click+=async delegate{await refresh();};
   Action<AppRow> choose=source=>{if(source==null||String.IsNullOrWhiteSpace(source.Path))return;if(ChooseAssociationTarget(d,source)){d.DialogResult=true;RefreshAssociations();ReloadCollections();}};table.MouseDoubleClick+=delegate(object sender,MouseButtonEventArgs e){var row=ItemsControl.ContainerFromElement(table,e.OriginalSource as DependencyObject) as DataGridRow;if(row!=null)choose(row.Item as AppRow);};
   ((Button)g.FindName("Pick")).Click+=delegate{PickAssociationWindow(d,table,choose);};d.Closed+=delegate{done=true;};d.Loaded+=async delegate{await refresh();if(pick==true&&!done)PickAssociationWindow(d,table,choose);};d.ShowDialog();
  }
  void PickAssociationWindow(Window owner,DataGrid table,Action<AppRow> choose){owner.Hide();w.Hide();bool released=false;var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(45)};DateTime end=DateTime.UtcNow.AddSeconds(30);timer.Tick+=async delegate{bool down=(Native.GetAsyncKeyState(1)&0x8000)!=0;if((Native.GetAsyncKeyState(27)&0x8000)!=0||DateTime.UtcNow>end){timer.Stop();Show();owner.Show();return;}if(!down){released=true;return;}if(!released)return;timer.Stop();Native.POINT point;Native.GetCursorPos(out point);int pid=(int)Native.Pid(Native.GetAncestor(Native.WindowFromPoint(point),2));Show();owner.Show();try{var result=await Task.Run(()=>scanPrograms(true,false,new string[0]));var row=db.FilterVisible(result.Rows).FirstOrDefault(r=>r.Processes.Any(p=>p.Pid==pid));if(row==null)throw new IOException("未找到可用的程序窗口，或此程序已被隐藏");db.ApplyName(row);ProgramPresentation.LoadIcon(row);choose(row);}catch(Exception ex){ModernDialog.Confirm(owner,ex.Message,"",false);}};owner.Closed+=delegate{timer.Stop();};timer.Start();}
  StackPanel AssociationInfo(AppRow row,bool editable,Window owner){ProgramPresentation.LoadIcon(row);db.ApplyName(row);var panel=new StackPanel{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(12)};panel.Children.Add(new Image{Source=row.Icon,Width=56,Height=56,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,18)});var name=FeatureUi.Label(row.Name,false);name.FontSize=20;name.FontWeight=FontWeights.SemiBold;if(editable){name.ToolTip="双击自定义名称";name.MouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){if(e.ClickCount==2){RenameProgram(owner,row);name.Text=row.Name;}};}panel.Children.Add(name);panel.Children.Add(FeatureUi.Label(row.Path,true));if(editable){panel.Children.Add(FeatureUi.Label("启动参数",true));var args=new TextBox{Text=row.Args,MinHeight=38};args.TextChanged+=delegate{row.Args=args.Text;};panel.Children.Add(args);var admin=new CheckBox{Content="管理员启动",IsChecked=row.Admin,Margin=new Thickness(0,16,0,0)};admin.SetResourceReference(FrameworkElement.StyleProperty,"Switch");admin.Checked+=delegate{row.Admin=true;};admin.Unchecked+=delegate{row.Admin=false;};panel.Children.Add(admin);}return panel;}
  bool ChooseAssociationTarget(Window owner,AppRow source){var g=FeatureUi.Parse("<Grid.RowDefinitions><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions>");var d=FeatureUi.Dialog(owner,"关联启动",660,420,g);g.Children.Add(AssociationInfo(source,false,d));var b=FeatureUi.Button("选择关联启动的程序",delegate{var target=ChooseLaunchFile(d);if(target!=null&&EditAssociation(d,source,target))d.DialogResult=true;},true);Grid.SetRow(b,1);b.HorizontalAlignment=HorizontalAlignment.Right;g.Children.Add(b);return d.ShowDialog()==true;}
  internal Func<Window,AppRow> launchFilePicker=null;
  AppRow ChooseLaunchFile(Window owner){if(launchFilePicker!=null)return launchFilePicker(owner);var picker=new Microsoft.Win32.OpenFileDialog{Title="选择关联启动的程序",Filter="所有文件 (*.*)|*.*",CheckFileExists=true};if(picker.ShowDialog(owner)!=true)return null;return new AppRow{Path=picker.FileName,Name=Path.GetFileNameWithoutExtension(picker.FileName),ProcessName=Path.GetFileName(picker.FileName),Args="",ArgsKnown=true,Selected=true};}
  bool EditAssociation(Window owner,AppRow source,AppRow initial){var target=ProgramPresentation.Copy(initial);var g=FeatureUi.Parse("<Grid.RowDefinitions><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><Grid x:Name='Relation'><Grid.ColumnDefinitions><ColumnDefinition Width='*'/><ColumnDefinition Width='110'/><ColumnDefinition Width='*'/></Grid.ColumnDefinitions></Grid><StackPanel x:Name='Actions' Grid.Row='1' Orientation='Horizontal' HorizontalAlignment='Right' Margin='0,20,0,0'/>");var anchor=owner;while(anchor.Owner!=null&&anchor.Width<900)anchor=anchor.Owner;var d=FeatureUi.Dialog(anchor,"确认关联启动",940,550,g);DialogPosition.CenterOnOwner(d);var relation=(Grid)g.FindName("Relation");Action render=delegate{relation.Children.Clear();relation.Children.Add(AssociationInfo(source,false,d));var icon=new Image{Width=88,Height=88,VerticalAlignment=VerticalAlignment.Center};using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("TrayLeaf.Assets.LinkedLaunch.png")){if(stream!=null){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();icon.Source=image;}}Grid.SetColumn(icon,1);relation.Children.Add(icon);var info=AssociationInfo(target,true,d);Grid.SetColumn(info,2);relation.Children.Add(info);};var actions=(StackPanel)g.FindName("Actions");actions.Children.Add(FeatureUi.Button("重新选择",delegate{var next=ChooseLaunchFile(d);if(next!=null){target=next;render();}},false));actions.Children.Add(FeatureUi.Button("确认关联",delegate{try{db.SaveAssociation(source,target,true);d.DialogResult=true;}catch(Exception ex){ModernDialog.Confirm(d,ex.Message,"",false);}},true));render();bool result=d.ShowDialog()==true;if(result){RefreshAssociations();ReloadCollections();}return result;}
 }
